# Generated by Switchyard (template coredns-lan); changed with `switchyard deploy refresh-plan`.
# No `log` plugin: queries are not logged. No health, ready or metrics listener.
{{zone}}:5353 {
    errors
    hosts /etc/coredns/hosts {
        ttl 60
        reload 5s
        fallthrough
    }
    file /etc/coredns/zone.db {{zone}}
}
.:5353 {
    errors
    hosts /etc/coredns/hosts {
        ttl 60
        reload 5s
        fallthrough
    }
    cache 300
    forward . {{upstreams}}
}
